USE KU_Sports;
GO
IF OBJECT_ID('dbo.STUDENTS') IS NULL
CREATE TABLE dbo.STUDENTS(StudentID VARCHAR(10) PRIMARY KEY,FullName VARCHAR(100) NOT NULL,Email VARCHAR(100),PasswordHash VARCHAR(255) NULL,IsActive BIT NOT NULL DEFAULT 1);
IF OBJECT_ID('dbo.COURTS') IS NULL
CREATE TABLE dbo.COURTS(CourtID INT IDENTITY PRIMARY KEY,CourtName VARCHAR(30) NOT NULL,CourtStatus VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',CONSTRAINT CK_CourtStatus CHECK(CourtStatus IN('ACTIVE','MAINTENANCE','CLOSED')));
IF OBJECT_ID('dbo.TIME_SLOTS') IS NULL
CREATE TABLE dbo.TIME_SLOTS(SlotID INT IDENTITY PRIMARY KEY,StartTime TIME NOT NULL,EndTime TIME NOT NULL,IsActive BIT NOT NULL DEFAULT 1,CONSTRAINT CK_SlotTime CHECK(StartTime<EndTime));
IF OBJECT_ID('dbo.FACILITY_SCHEDULE') IS NULL
CREATE TABLE dbo.FACILITY_SCHEDULE(ScheduleID INT IDENTITY PRIMARY KEY,ScheduleDate DATE NOT NULL UNIQUE,IsCourtOpen BIT NOT NULL,ActivityName VARCHAR(200),Description VARCHAR(500));
IF OBJECT_ID('dbo.BOOKINGS') IS NULL
CREATE TABLE dbo.BOOKINGS(BookingID INT IDENTITY PRIMARY KEY,CourtID INT NOT NULL REFERENCES dbo.COURTS(CourtID),SlotID INT NOT NULL REFERENCES dbo.TIME_SLOTS(SlotID),BookingDate DATE NOT NULL DEFAULT CAST(GETDATE() AS DATE),StudentID1 VARCHAR(10) NOT NULL REFERENCES dbo.STUDENTS(StudentID),StudentID2 VARCHAR(10) NOT NULL REFERENCES dbo.STUDENTS(StudentID),Status VARCHAR(20) NOT NULL DEFAULT 'BOOKED',CreatedAt DATETIME NOT NULL DEFAULT GETDATE(),CancelledAt DATETIME,CONSTRAINT CK_DifferentStudents CHECK(StudentID1<>StudentID2),CONSTRAINT CK_BookingStatus CHECK(Status IN('BOOKED','CANCELLED')));
IF OBJECT_ID('dbo.DONATIONS') IS NULL
CREATE TABLE dbo.DONATIONS(DonationID INT IDENTITY PRIMARY KEY,BookingID INT NOT NULL REFERENCES dbo.BOOKINGS(BookingID),Amount DECIMAL(10,2) NOT NULL CHECK(Amount>0),PaymentMethod VARCHAR(30) NOT NULL DEFAULT 'PROMPTPAY_DEMO',DonationDate DATETIME NOT NULL DEFAULT GETDATE());
IF OBJECT_ID('dbo.BOOKING_LOGS') IS NULL
CREATE TABLE dbo.BOOKING_LOGS(LogID INT IDENTITY PRIMARY KEY,BookingID INT NOT NULL REFERENCES dbo.BOOKINGS(BookingID),ActionType VARCHAR(30) NOT NULL,OldStatus VARCHAR(20),NewStatus VARCHAR(20),ChangedAt DATETIME NOT NULL DEFAULT GETDATE());
IF OBJECT_ID('dbo.STAFF_USERS') IS NULL
CREATE TABLE dbo.STAFF_USERS(StaffID INT IDENTITY PRIMARY KEY,Username VARCHAR(50) UNIQUE NOT NULL,PasswordHash VARCHAR(255) NOT NULL,Role VARCHAR(20) NOT NULL DEFAULT 'ADMIN',IsActive BIT NOT NULL DEFAULT 1);
GO
